      "homework_pass": "Homework Pass",
      "line_leader": "Line Leader",
      "looks_like": "Often looks like",
      "lunch_with_teacher": "Lunch with Teacher",
      "matched_intervention": "Matched intervention",
      "mystery_prize": "Mystery Prize",
